args.query:
select count(*) d, sum(case when cast(o.order_delivered_customer_date as date) > cast(o.order_estimated_delivery_date as date) then 1 else 0 end) late
from orders o join customers c using(customer_id)
where c.customer_state='AL' and o.order_status='delivered' and o.order_delivered_customer_date is not null
